import { common } from '@kit.AbilityKit';
import {
  CallbackEvergreenPageOwner,
  EvergreenPageOwner
} from '../integration/EvergreenPageIntegration';
import { EvergreenLaunchContext } from '../model/EvergreenLaunchContext';
import { EvergreenStore } from '../model/EvergreenStore';

@Entry
@Component
struct Index {
  @State surface: string = 'main';
  @State accountEncouragementVisible: boolean = false;
  @State accountEncouragementHeading: string = '';
  @State accountEncouragementSummary: string = '';
  @State articleTitle: string = '';
  @State articleIdentifier: string = '';
  @State account: string = 'logged_out';
  private store: EvergreenStore = new EvergreenStore();
  private runtimeOwnerId: string = 'EvergreenIndex:' + String(Date.now());
  private mounted: boolean = false;

  async aboutToAppear(): Promise<void> {
    const owner: EvergreenPageOwner = this.createRuntimeOwner();
    EvergreenLaunchContext.attach(owner);
    const context: common.UIAbilityContext | undefined = this.hostContext();
    if (context === undefined || this.mounted) {
      return;
    }
    this.mounted = true;
    try {
      await owner.mount(context, EvergreenLaunchContext.productionInput(context));
      this.applyState();
      // An ordinary foreground launch is where the encouragement is considered.
      await owner.dispatch({ 'name': 'resumeApplication' });
    } catch (error) {
      console.error('Index: mounting the evergreen account encouragement failed: ' + String(error));
    }
    this.applyState();
  }

  aboutToDisappear(): void {
    EvergreenLaunchContext.detach(this.createRuntimeOwner());
    this.mounted = false;
  }

  createRuntimeOwner(): EvergreenPageOwner {
    const store = this.store;
    const ownerId = this.runtimeOwnerId;
    return new CallbackEvergreenPageOwner(
      async (context, input): Promise<void> => { await store.mount(context, input); },
      async (event): Promise<void> => { await store.dispatch(event); this.applyState(); },
      async (): Promise<boolean> => store.ordinaryLaunchWouldShow(),
      (): Record<string, Object> => store.currentState(), (): Record<string, Object> => store.currentPersistence(),
      (): Record<string, Object> => store.currentDecision(), (): Record<string, Object> => store.currentDecisionAfterRelaunch(),
      (): Record<string, Object> => store.currentRouting(), (): string[] => store.currentHistoryDays(),
      (): boolean => store.featureAvailable(), (): string => ownerId
    );
  }

  private hostContext(): common.UIAbilityContext | undefined {
    const host: common.Context | undefined = this.getUIContext().getHostContext();
    return host as common.UIAbilityContext | undefined;
  }

  private applyState(): void {
    const state: Record<string, Object> = this.store.currentState();
    this.surface = String(state['surface']);
    this.accountEncouragementVisible = state['accountEncouragementVisible'] === true;
    this.articleTitle = String(state['articleTitle']);
    this.articleIdentifier = String(state['article']);
    this.account = String(state['account']);
    this.accountEncouragementHeading = String(state['encouragementState']);
    this.accountEncouragementSummary = this.summaryFrom(state);
  }

  private summaryFrom(state: Record<string, Object>): string {
    const details: Object | undefined = state['encouragement'];
    if (details === undefined || details === null || typeof details !== 'object') {
      return '';
    }
    const record: Record<string, Object> = details as Record<string, Object>;
    const days: number = Number(String(record['readingDayCount']));
    const articles: number = Number(String(record['articlesReadInWindow']));
    const saved: number = Number(String(record['savedCount']));
    const impressions: number = Number(String(record['impressionCount']));
    return 'You have read ' + String(articles) + ' article reads on ' + String(days) + ' recent days, '
      + String(saved) + ' saved. Encouragement ' + String(impressions) + ' of 2 shown.';
  }

  private handleAction(name: string): void {
    this.send(name);
  }

  private async send(name: string): Promise<void> {
    try {
      await this.store.dispatch({ 'name': name });
    } catch (error) {
      console.error('Index: ' + name + ' failed: ' + String(error));
    }
    this.applyState();
  }

  @Builder
  accountEncouragementCard() {
    Column({ space: 12 }) {
      Text('Create an account to get more out of Wikipedia')
        .fontSize(20)
        .fontWeight(FontWeight.Bold)
      Text(this.accountEncouragementSummary).fontSize(14)
      Text('Reader state: ' + this.accountEncouragementHeading).fontSize(12)
      Row({ space: 12 }) {
        Button('Maybe later')
          .onClick(() => { this.handleAction('pressMaybeLater'); })
        Button('Create account')
          .onClick(() => { this.handleAction('pressCreateAccount'); })
      }
      Button('Close')
        .onClick(() => { this.handleAction('pressPermanentClose'); })
    }
    .width('100%')
    .padding(16)
    .backgroundColor('#FFFFFF')
    .borderRadius(12)
  }

  build() {
    Column({ space: 18 }) {
      Text('Wikipedia').fontSize(30).fontWeight(FontWeight.Bold)
      Text(this.surface).fontSize(20)
      if (this.surface === 'article') {
        Text(this.articleIdentifier).fontSize(16)
        Text(this.articleTitle).fontSize(18)
      }
      if (this.accountEncouragementVisible) {
        this.accountEncouragementCard()
      }
    }.width('100%').height('100%').padding(24)
  }
}

