import { AbilityConstant, UIAbility, Want } from '@kit.AbilityKit';
import { window } from '@kit.ArkUI';
import { EvergreenLaunchContext } from '../model/EvergreenLaunchContext';

/**
 * Production entry of the application.
 *
 * The ability only publishes launch information to the application-owned
 * `EvergreenLaunchContext` and loads the ArkUI page that owns the evergreen
 * account-creation encouragement.  Launch classification happens here: an
 * article URI means an external deep link, which the page routes ahead of the
 * encouragement.
 */
export default class EntryAbility extends UIAbility {
  onCreate(want: Want, launchParam: AbilityConstant.LaunchParam): void {
    EvergreenLaunchContext.updateFromWant(want);
  }

  onWindowStageCreate(windowStage: window.WindowStage): void {
    windowStage.loadContent('pages/Index').catch((error: Error) => {
      console.error('EntryAbility: loading pages/Index failed: ' + String(error && error.message));
    });
  }

  /** A deep link can arrive while the application is already running. */
  onNewWant(want: Want): void {
    EvergreenLaunchContext.updateFromWant(want);
    const uri: string = want !== undefined && want.uri !== undefined ? want.uri : '';
    if (uri.length === 0) {
      return;
    }
    EvergreenLaunchContext.openExternalArticle(uri);
  }

  onDestroy(): void {
    EvergreenLaunchContext.reset();
  }
}

