private declaredLaunchOf(event: Record<string, Object>): EvergreenLaunchKind | undefined {
    const raw: string = firstText(event, ['launch', 'launchtype', 'intent', 'type', 'action']);
    if (raw.length === 0) {
      return undefined;
    }
    return parseLaunchKind(raw);
  }

  private uriOf(event: Record<string, Object>): string {
    const raw: string = firstText(event, ['uri', 'deeplink', 'deeplinkuri', 'url', 'target']);
    return raw.length > 0 ? raw : this.deepLinkUri;
  }

  private authenticationResultOf(event: Record<string, Object>, name: string): string {
    const explicit: string = firstText(event, AUTH_RESULT_KEYS);
    if (explicit.length > 0) {
      return explicit.toLowerCase();
    }
    if (containsAny(name, ['cancel', 'abort'])) {
      return 'cancelled';
    }
    if (containsAny(name, ['fail', 'error'])) {
      return 'failed';
    }
    if (containsAny(name, ['success'])) {
      return 'success_permanent_account';
    }
    if (this.authenticationRequested && containsAny(name, ['complete', 'completed', 'finish', 'finished', 'result'])) {
      return 'success_permanent_account';
    }
    return '';
  }

