/**
   * Event payloads may describe a launch or an authentication outcome either at
   * the top level or inside a nested `launch` / `authentication` object, so both
   * shapes are resolved, most specific first.
   */
  private eventSources(event: Record<string, Object>, nestedKeys: string[]): Array<Record<string, Object> | undefined> {
    const sources: Array<Record<string, Object> | undefined> = [];
    for (let index = 0; index < nestedKeys.length; index++) {
      const nested: Object | undefined = lookupValue(event, nestedKeys[index]);
      if (nested !== undefined && nested !== null && typeof nested === 'object' && !Array.isArray(nested)) {
        sources.push(nested as Record<string, Object>);
      }
    }
    sources.push(event);
    return sources;
  }

  private declaredLaunchOf(event: Record<string, Object>): EvergreenLaunchKind | undefined {
    const sources: Array<Record<string, Object> | undefined> = this.eventSources(event, EVENT_NESTED_LAUNCH_KEYS);
    const raw: string = firstText(sources[0], ['type', 'launchtype', 'intent', 'action']);
    if (raw.length === 0) {
      const top: string = firstText(event, ['launch', 'launchtype', 'intent', 'type', 'action']);
      if (top.length === 0) {
        return undefined;
      }
      return parseLaunchKind(top);
    }
    return parseLaunchKind(raw);
  }

  private uriOf(event: Record<string, Object>): string {
    const sources: Array<Record<string, Object> | undefined> = this.eventSources(event, EVENT_NESTED_LAUNCH_KEYS);
    for (let index = 0; index < sources.length; index++) {
      const raw: string = firstText(sources[index], ['uri', 'deeplink', 'deeplinkuri', 'targeturi', 'url', 'target']);
      if (raw.length > 0) {
        return raw;
      }
    }
    return this.deepLinkUri;
  }

  private authenticationResultOf(event: Record<string, Object>, name: string): string {
    const sources: Array<Record<string, Object> | undefined> =
      this.eventSources(event, EVENT_NESTED_AUTH_KEYS);
    for (let index = 0; index < sources.length; index++) {
      const explicit: string = firstText(sources[index], AUTH_RESULT_KEYS);
      if (explicit.length > 0) {
        return explicit.toLowerCase();
      }
    }
    if (containsAny(name, ['cancel', 'abort'])) {
      return 'cancelled';
    }
    if (containsAny(name, ['fail', 'error'])) {
      return 'failed';
    }
    if (containsAny(name, ['success'])) {
      return 'success_permanent_account';
    }
    if (this.authenticationRequested && containsAny(name, ['complete', 'completed', 'finish', 'finished', 'result'])) {
      return 'success_permanent_account';
    }
    return '';
  }

