private isAuthenticationIntent(name: string, event: Record<string, Object>): boolean {
    if (containsAny(name, ['auth', 'accountcreation', 'createaccount', 'register', 'signup', 'signin',
      'login', 'createnew'])) {
      return true;
    }
    const sources: Array<Record<string, Object> | undefined> = this.eventSources(event, EVENT_NESTED_AUTH_KEYS);
    for (let index = 0; index < sources.length; index++) {
      if (firstText(sources[index], AUTH_RESULT_KEYS).length > 0) {
        return this.authenticationRequested || containsAny(name, ['result', 'outcome']);
      }
    }
    return false;
  }

